package net.battlespades.bot;
import java.util.*;
/** Collision-only worker map: four 64-bit words per column, no colors, live-world references or native handles. */
public final class CompactVoxelMap {
    public static final int SIZE=512,HEIGHT=240,AREA=SIZE*SIZE;private final Thread owner=Thread.currentThread();private final long[] columns=new long[AREA*4];private final int shift;
    private record Scan(int columns,int maximum,boolean classic){}
    private static int u8(byte[] bytes,int position){if(position<0||position>=bytes.length)throw new IllegalArgumentException("Truncated VXL snapshot");return bytes[position]&255;}
    private static Scan scan(byte[] bytes){int position=0,count=0,maximum=0;boolean classic=true;while(position<bytes.length){int words,start,end,air;while(true){words=u8(bytes,position);start=u8(bytes,position+1);end=u8(bytes,position+2);air=u8(bytes,position+3);maximum=Math.max(maximum,Math.max(start,Math.max(end,air)));classic&=end<64;if(words==0)break;position+=words*4;}position+=4+Math.max(0,end-start+1)*4;if(++count>AREA)throw new IllegalArgumentException("Too many VXL columns");}if(position!=bytes.length)throw new IllegalArgumentException("Invalid VXL column stream");return new Scan(count,maximum,classic);}
    public CompactVoxelMap(byte[] source,String format){Objects.requireNonNull(source);byte[] bytes=source.clone();var scan=scan(bytes);int edge=(int)Math.sqrt(scan.columns());if(edge<=0||edge*edge!=scan.columns()||edge>SIZE)throw new IllegalArgumentException("Invalid VXL column stream");if(!Set.of("auto","retail","classic64").contains(format))throw new IllegalArgumentException("Unknown VXL source format");boolean classic=format.equals("classic64")||format.equals("auto")&&edge==SIZE&&scan.maximum()<=64&&scan.classic();if(classic&&(edge!=SIZE||scan.maximum()>64))throw new IllegalArgumentException("Classic VXL requires 512 x 512 x 64");shift=classic?176:Math.max(0,239-scan.maximum());for(int i=0;i<AREA;i++)set(i,239,true);int offset=(SIZE-edge)/2,position=0,depth=classic?64:HEIGHT;var markers=new ArrayList<BotState.Cell>();
        for(int sy=0;sy<edge;sy++)for(int sx=0;sx<edge;sx++){int x=sx+offset,y=sy+offset,col=y*SIZE+x;boolean surface=false;while(true){int span=position,words=u8(bytes,position),start=u8(bytes,position+1),end=u8(bytes,position+2),air=u8(bytes,position+3);if(start>depth||end>=depth||air>depth||start>end+1)throw new IllegalArgumentException("Out-of-range VXL span");position+=4;int length=Math.max(0,end-start+1);if(position+(long)length*4>bytes.length)throw new IllegalArgumentException("Truncated VXL colors");range(col,start+shift,start+shift+length);for(int i=0;i<length;i++){int at=position+i*4,color=u8(bytes,at)|u8(bytes,at+1)<<8|u8(bytes,at+2)<<16;if(!classic&&marker(color))markers.add(new BotState.Cell(x,y,start+shift+i));}position+=length*4;surface|=length>0;if(words==0){if(surface)range(col,end+1+shift,HEIGHT);break;}int bottom=words-length-1,next=span+words*4;if(bottom<0||next+4>bytes.length||position+bottom*4!=next)throw new IllegalArgumentException("Invalid VXL bottom span");int nextAir=u8(bytes,next+3),nextStart=u8(bytes,next+1);if(nextAir>nextStart||nextStart<=start)throw new IllegalArgumentException("Overlapping VXL air span");int bottomStart=nextAir-bottom;if(bottomStart<end+1)throw new IllegalArgumentException("Overlapping VXL spans");range(col,end+1+shift,bottomStart+bottom+shift);for(int i=0;i<bottom;i++){int at=position+i*4,color=u8(bytes,at)|u8(bytes,at+1)<<8|u8(bytes,at+2)<<16;if(!classic&&marker(color))markers.add(new BotState.Cell(x,y,bottomStart+shift+i));}position+=bottom*4;}}
        if(position!=bytes.length)throw new IllegalArgumentException("Trailing VXL data");var removable=markers.stream().filter(c->solid(c.x(),c.y(),c.z())&&!solid(c.x(),c.y(),c.z()-1)&&!solid(c.x(),c.y(),c.z()-2)).toList();for(var c:removable)set(c.x(),c.y(),c.z(),false);
    }
    private static boolean marker(int color){int value=color&0xf0f0f0;return value==0xf0||value==0xf000;}private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Collision snapshot outside worker");}
    private void range(int column,int from,int end){for(int z=Math.max(0,from);z<Math.min(HEIGHT,end);z++)set(column,z,true);}private void set(int column,int z,boolean solid){int index=column*4+(z>>>6);long bit=1L<<(z&63);if(solid)columns[index]|=bit;else columns[index]&=~bit;}
    public int sourceZShift(){owned();return shift;}public long word(int column,int word){owned();return columns[column*4+word];}
    public boolean solid(int x,int y,int z){owned();return x>=0&&x<SIZE&&y>=0&&y<SIZE&&z>=0&&z<HEIGHT&&(columns[(y*SIZE+x)*4+(z>>>6)]&(1L<<(z&63)))!=0;}
    public void set(int x,int y,int z,boolean value){owned();if(x>=0&&x<SIZE&&y>=0&&y<SIZE&&z>=0&&z<HEIGHT)set(y*SIZE+x,z,value);}
    public int surfaceZ(int x,int y){owned();if(x<0||x>=SIZE||y<0||y>=SIZE)return HEIGHT;int column=y*SIZE+x;for(int word=0;word<4;word++){long value=columns[column*4+word];if(value!=0)return word*64+Long.numberOfTrailingZeros(value);}return HEIGHT;}
}
